# Export cau truc bang + stored procedure ra file .sql (Schema only, giong SSMS Script as CREATE)
# Can co SMO: cai SSMS hoac SQL Server SDK (thu muc SDK\Assemblies)
#
# Vi du:
#   .\Export-SqlSchema.ps1 `
#     -ConnectionString "Server=.;Database=MyDb;Integrated Security=True;" `
#     -OutputFile "D:\temp\schema.sql" `
#     -Tables "ACC_Receipt","ACC_ReceiptDetail" `
#     -StoredProcedures "ACC_Receipt_GetById"
#
#   .\Export-SqlSchema.ps1 -ConnectionString "..." -OutputFile "..." -TablesFile "D:\tables.txt"

param(
    [Parameter(Mandatory = $true)]
    [string] $ConnectionString,

    [Parameter(Mandatory = $true)]
    [string] $OutputFile,

    [string[]] $Tables = @(),

    [string[]] $StoredProcedures = @(),

    [string] $TablesFile = "",

    [string] $StoredProceduresFile = "",

    [switch] $IncludeTableIndexes,

    [switch] $IncludeTableForeignKeys
)

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function Import-SmoAssemblies
{
    $loaded = [System.AppDomain]::CurrentDomain.GetAssemblies() |
        Where-Object { $_.GetName().Name -eq "Microsoft.SqlServer.Smo" }
    if ($loaded -and $loaded.Count -gt 0)
    {
        return
    }

    $searchRoots = @()
    $sqlVerFolders = @("160", "150", "140", "130", "120", "110", "100")
    foreach ($ver in $sqlVerFolders)
    {
        $searchRoots += "C:\Program Files\Microsoft SQL Server\$ver\SDK\Assemblies"
    }

    $ssmsBase = "C:\Program Files (x86)\Microsoft SQL Server"
    if (Test-Path $ssmsBase)
    {
        Get-ChildItem -Path $ssmsBase -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $searchRoots += Join-Path $_.FullName "SDK\Assemblies"
        }
    }

    $smoDll = $null
    foreach ($root in $searchRoots)
    {
        $candidate = Join-Path $root "Microsoft.SqlServer.Smo.dll"
        if (Test-Path $candidate)
        {
            $smoDll = $candidate
            break
        }
    }

    if (-not $smoDll)
    {
        throw "Khong tim thay Microsoft.SqlServer.Smo.dll. Hay cai SSMS hoac SQL Server SDK."
    }

    $asmDir = Split-Path -Parent $smoDll
    $required = @(
        "Microsoft.SqlServer.ConnectionInfo.dll",
        "Microsoft.SqlServer.Management.Sdk.Sfc.dll",
        "Microsoft.SqlServer.Smo.dll",
        "Microsoft.SqlServer.SqlEnum.dll"
    )

    foreach ($name in $required)
    {
        $path = Join-Path $asmDir $name
        if (-not (Test-Path $path))
        {
            throw "Thieu file: $path"
        }
        [void][System.Reflection.Assembly]::LoadFrom($path)
    }
}

function Read-NameListFromFile
{
    param([string] $Path)

    if ([string]::IsNullOrWhiteSpace($Path))
    {
        return @()
    }
    if (-not (Test-Path $Path))
    {
        throw "Khong tim thay file: $Path"
    }

    $lines = Get-Content -Path $Path -Encoding UTF8
    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines)
    {
        $t = $line.Trim()
        if ($t.Length -eq 0) { continue }
        if ($t.StartsWith("#")) { continue }
        [void]$result.Add($t)
    }
    return $result.ToArray()
}

function Split-SchemaObjectName
{
    param([string] $FullName)

    $parts = $FullName.Split(".", [StringSplitOptions]::RemoveEmptyEntries)
    if ($parts.Length -ge 2)
    {
        $schema = $parts[$parts.Length - 2]
        $name = $parts[$parts.Length - 1]
        return @{ Schema = $schema; Name = $name }
    }

    return @{ Schema = "dbo"; Name = $FullName }
}

function Connect-SmoServer
{
    param([string] $ConnStr)

    $builder = New-Object System.Data.SqlClient.SqlConnectionStringBuilder
    $builder.ConnectionString = $ConnStr

    if ([string]::IsNullOrWhiteSpace($builder.DataSource))
    {
        throw "Connection string thieu Server/Data Source."
    }
    if ([string]::IsNullOrWhiteSpace($builder.InitialCatalog))
    {
        throw "Connection string thieu Database/Initial Catalog."
    }

    $server = New-Object Microsoft.SqlServer.Management.Smo.Server $builder.DataSource

    if ($builder.IntegratedSecurity)
    {
        $server.ConnectionContext.LoginSecure = $true
    }
    else
    {
        $server.ConnectionContext.LoginSecure = $false
        $server.ConnectionContext.Login = $builder.UserID
        $server.ConnectionContext.Password = $builder.Password
    }

    if ($builder.ContainsKey("Connect Timeout") -and $builder["Connect Timeout"])
    {
        $server.ConnectionContext.ConnectTimeout = [int]$builder["Connect Timeout"]
    }

    $db = $server.Databases[$builder.InitialCatalog]
    if (-not $db)
    {
        throw ("Khong tim thay database: {0}" -f $builder.InitialCatalog)
    }

    return @{ Server = $server; Database = $db; DatabaseName = $builder.InitialCatalog }
}

Import-SmoAssemblies

$tableNames = @($Tables)
if (-not [string]::IsNullOrWhiteSpace($TablesFile))
{
    $tableNames += @(Read-NameListFromFile -Path $TablesFile)
}

$spNames = @($StoredProcedures)
if (-not [string]::IsNullOrWhiteSpace($StoredProceduresFile))
{
    $spNames += @(Read-NameListFromFile -Path $StoredProceduresFile)
}

$tableNames = $tableNames | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
$spNames = $spNames | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique

if ($tableNames.Count -eq 0 -and $spNames.Count -eq 0)
{
    throw "Can truyen -Tables / -StoredProcedures hoac file -TablesFile / -StoredProceduresFile."
}

$conn = Connect-SmoServer -ConnStr $ConnectionString
$server = $conn.Server
$database = $conn.Database

$scripter = New-Object Microsoft.SqlServer.Management.Smo.Scripter $server
$scripter.Options.ScriptSchema = $true
$scripter.Options.ScriptData = $false
$scripter.Options.IncludeHeaders = $true
$scripter.Options.Indexes = [bool]$IncludeTableIndexes
$scripter.Options.DriAllConstraints = [bool]$IncludeTableForeignKeys
$scripter.Options.Triggers = $true
$scripter.Options.NoCommandTerminator = $false
$scripter.Options.ToFileOnly = $true
$scripter.Options.FileName = $OutputFile
$scripter.Options.Encoding = [System.Text.Encoding]::UTF8

$urns = New-Object System.Collections.Generic.List[Microsoft.SqlServer.Management.Sdk.Sfc.Urn]

foreach ($tableFullName in $tableNames)
{
    $parsed = Split-SchemaObjectName -FullName $tableFullName
    $table = $database.Tables[$parsed.Name, $parsed.Schema]
    if (-not $table)
    {
        throw ("Khong tim thay bang: [{0}].[{1}]" -f $parsed.Schema, $parsed.Name)
    }
    [void]$urns.Add($table.Urn)
}

foreach ($spFullName in $spNames)
{
    $parsed = Split-SchemaObjectName -FullName $spFullName
    $proc = $database.StoredProcedures[$parsed.Name, $parsed.Schema]
    if (-not $proc)
    {
        throw ("Khong tim thay stored procedure: [{0}].[{1}]" -f $parsed.Schema, $parsed.Name)
    }
    if ($proc.IsSystemObject)
    {
        throw ("Bo qua system procedure: [{0}].[{1}]" -f $parsed.Schema, $parsed.Name)
    }
    [void]$urns.Add($proc.Urn)
}

$outputDir = Split-Path -Parent $OutputFile
if (-not [string]::IsNullOrWhiteSpace($outputDir) -and -not (Test-Path $outputDir))
{
    New-Item -ItemType Directory -Path $outputDir -Force | Out-Null
}

if (Test-Path $OutputFile)
{
    Remove-Item -Path $OutputFile -Force
}

$header = @(
    "-- Generated: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
    "-- Database: $($conn.DatabaseName)"
    "-- Tables: $($tableNames -join ', ')"
    "-- StoredProcedures: $($spNames -join ', ')"
    "USE [$($conn.DatabaseName)]"
    "GO"
    ""
)
$header | Out-File -FilePath $OutputFile -Encoding UTF8

$scripter.Options.AppendToFile = $true
$scripter.Script($urns.ToArray()) | Out-Null

Write-Host ("Da xuat script: {0}" -f (Resolve-Path $OutputFile))

# =============================================================================
# Sua CONNECTION_STRING roi chay file nay (PowerShell):
#   cd "G:\0.DỰ ÁN\Z.WEB-CDN-QUYNHON\sql\25.092026"
#   .\Run-Export.ps1
#
# Tao 3 file trong cung thu muc:
#   01_TableStructure.sql   - CREATE bang (GEN_, HRS_, ...)
#   02_StoreStructure.sql   - CREATE stored procedure
#   03_Data.sql             - INSERT du lieu cac bang tren
# =============================================================================

#region --- CAU HINH (sua o day) ---

$ConnectionString = "Server=.;Database=SIMS_NET;Integrated Security=True;"

# Bang: ten bat dau bang cac tien to nay (schema dbo)
$TableNamePrefixes = @("GEN_", "HRS_", "_GEN_")

# Store: ten bat dau bang cac tien to nay
$StoredProcedurePrefixes = @("GEN_", "HRS_")

# Bo qua bang/SP co chuoi nay trong ten (vd backup)
$ExcludeNameContains = @("_Bak_", "_Bak")

$OutputFolder = $PSScriptRoot
$FileTableStructure = Join-Path $OutputFolder "01_TableStructure.sql"
$FileStoreStructure = Join-Path $OutputFolder "02_StoreStructure.sql"
$FileData = Join-Path $OutputFolder "03_Data.sql"

#endregion

Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

