function Test-NameMatchPrefix
{
    param(
        [string] $Name,
        [string[]] $Prefixes
    )

    foreach ($prefix in $Prefixes)
    {
        if ($Name.StartsWith($prefix, [StringComparison]::OrdinalIgnoreCase))
        {
            return $true
        }
    }
    return $false
}

function Test-NameExcluded
{
    param(
        [string] $Name,
        [string[]] $ContainsList
    )

    foreach ($part in $ContainsList)
    {
        if ($Name.IndexOf($part, [StringComparison]::OrdinalIgnoreCase) -ge 0)
        {
            return $true
        }
    }
    return $false
}

function Get-FilteredTables
{
    param(
        $Database,
        [string[]] $Prefixes,
        [string[]] $ExcludeContains
    )

    $list = New-Object System.Collections.Generic.List[Microsoft.SqlServer.Management.Smo.Table]
    foreach ($table in $Database.Tables)
    {
        if ($table.IsSystemObject)
        {
            continue
        }
        if (-not (Test-NameMatchPrefix -Name $table.Name -Prefixes $Prefixes))
        {
            continue
        }
        if (Test-NameExcluded -Name $table.Name -ContainsList $ExcludeContains)
        {
            continue
        }
        [void]$list.Add($table)
    }

    return $list | Sort-Object Schema, Name
}

function Get-FilteredStoredProcedures
{
    param(
        $Database,
        [string[]] $Prefixes,
        [string[]] $ExcludeContains
    )

    $list = New-Object System.Collections.Generic.List[Microsoft.SqlServer.Management.Smo.StoredProcedure]
    foreach ($proc in $Database.StoredProcedures)
    {
        if ($proc.IsSystemObject)
        {
            continue
        }
        if (-not (Test-NameMatchPrefix -Name $proc.Name -Prefixes $Prefixes))
        {
            continue
        }
        if (Test-NameExcluded -Name $proc.Name -ContainsList $ExcludeContains)
        {
            continue
        }
        [void]$list.Add($proc)
    }

    return $list | Sort-Object Schema, Name
}

function Remove-OutputFiles
{
    param([string[]] $Paths)

    foreach ($path in $Paths)
    {
        if (Test-Path $path)
        {
            Remove-Item -Path $path -Force
            Write-Host ("Da xoa file cu: {0}" -f $path)
        }
    }
}

function Write-SqlFileHeader
{
    param(
        [string] $Path,
        [string] $DatabaseName,
        [string] $Description,
        [string[]] $ObjectNames
    )

    $header = @(
        "-- $Description"
        "-- Generated: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')"
        "-- Database: $DatabaseName"
        "-- So object: $($ObjectNames.Count)"
        "USE [$DatabaseName]"
        "GO"
        ""
    )
    $header | Out-File -FilePath $Path -Encoding UTF8
}

function Export-SmoObjectsToFile
{
    param(
        $Server,
        [string] $OutputPath,
        [Microsoft.SqlServer.Management.Sdk.Sfc.Urn[]] $Urns,
        [bool] $ScriptSchema,
        [bool] $ScriptData,
        [bool] $IncludeIndexes,
        [bool] $IncludeForeignKeys
    )

    if ($Urns -eq $null -or $Urns.Length -eq 0)
    {
        Write-Host ("Bo qua (khong co object): {0}" -f $OutputPath)
        return
    }

    $scripter = New-Object Microsoft.SqlServer.Management.Smo.Scripter $Server
    $scripter.Options.ScriptSchema = $ScriptSchema
    $scripter.Options.ScriptData = $ScriptData
    $scripter.Options.IncludeHeaders = $true
    $scripter.Options.Indexes = $IncludeIndexes
    $scripter.Options.DriAllConstraints = $IncludeForeignKeys
    $scripter.Options.Triggers = $ScriptSchema
    $scripter.Options.NoCommandTerminator = $false
    $scripter.Options.ToFileOnly = $true
    $scripter.Options.FileName = $OutputPath
    $scripter.Options.Encoding = [System.Text.Encoding]::UTF8
    $scripter.Options.AppendToFile = $true

    if ($ScriptData)
    {
        $scripter.Options.BatchSize = 100
    }

    $scripter.Script($Urns) | Out-Null
}

Import-SmoAssemblies

Write-Host "Dang ket noi SQL..."
$conn = Connect-SmoServer -ConnStr $ConnectionString
$server = $conn.Server
$database = $conn.Database
$dbName = $conn.DatabaseName

Write-Host "Dang loc bang GEN_/HRS_..."
$tables = @(Get-FilteredTables -Database $database -Prefixes $TableNamePrefixes -ExcludeContains $ExcludeNameContains)
Write-Host ("Tim thay {0} bang." -f $tables.Count)

Write-Host "Dang loc stored procedure..."
$procs = @(Get-FilteredStoredProcedures -Database $database -Prefixes $StoredProcedurePrefixes -ExcludeContains $ExcludeNameContains)
Write-Host ("Tim thay {0} stored procedure." -f $procs.Count)

if ($tables.Count -eq 0 -and $procs.Count -eq 0)
{
    throw "Khong co bang/SP nao khop tien to. Kiem tra CONNECTION_STRING va TableNamePrefixes."
}

Remove-OutputFiles -Paths @($FileTableStructure, $FileStoreStructure, $FileData)

$tableNames = @()
$tableUrns = New-Object System.Collections.Generic.List[Microsoft.SqlServer.Management.Sdk.Sfc.Urn]
foreach ($t in $tables)
{
    $tableNames += ("[{0}].[{1}]" -f $t.Schema, $t.Name)
    [void]$tableUrns.Add($t.Urn)
}

$procNames = @()
$procUrns = New-Object System.Collections.Generic.List[Microsoft.SqlServer.Management.Sdk.Sfc.Urn]
foreach ($p in $procs)
{
    $procNames += ("[{0}].[{1}]" -f $p.Schema, $p.Name)
    [void]$procUrns.Add($p.Urn)
}

if ($tables.Count -gt 0)
{
    Write-Host "Xuat cau truc bang..."
    Write-SqlFileHeader -Path $FileTableStructure -DatabaseName $dbName `
        -Description "Cau truc bang (CREATE TABLE, index, FK)" -ObjectNames $tableNames
    Export-SmoObjectsToFile -Server $server -OutputPath $FileTableStructure `
        -Urns $tableUrns.ToArray() -ScriptSchema $true -ScriptData $false `
        -IncludeIndexes $true -IncludeForeignKeys $true
    Write-Host (" -> {0}" -f $FileTableStructure)
}

if ($procs.Count -gt 0)
{
    Write-Host "Xuat cau truc stored procedure..."
    Write-SqlFileHeader -Path $FileStoreStructure -DatabaseName $dbName `
        -Description "Cau truc stored procedure (CREATE PROCEDURE)" -ObjectNames $procNames
    Export-SmoObjectsToFile -Server $server -OutputPath $FileStoreStructure `
        -Urns $procUrns.ToArray() -ScriptSchema $true -ScriptData $false `
        -IncludeIndexes $false -IncludeForeignKeys $false
    Write-Host (" -> {0}" -f $FileStoreStructure)
}

if ($tables.Count -gt 0)
{
    Write-Host "Xuat du lieu (co the lau neu nhieu dong)..."
    Write-SqlFileHeader -Path $FileData -DatabaseName $dbName `
        -Description "Du lieu bang (INSERT)" -ObjectNames $tableNames
    Export-SmoObjectsToFile -Server $server -OutputPath $FileData `
        -Urns $tableUrns.ToArray() -ScriptSchema $false -ScriptData $true `
        -IncludeIndexes $false -IncludeForeignKeys $false
    Write-Host (" -> {0}" -f $FileData)
}

Write-Host ""
Write-Host "Hoan tat. Chay tren DB test theo thu tu:"
Write-Host "  1) 01_TableStructure.sql"
Write-Host "  2) 02_StoreStructure.sql"
Write-Host "  3) 03_Data.sql"

