        throw "Chua dien SqlDatabase."
    }

    $smoServer = New-Object Microsoft.SqlServer.Management.Smo.Server $Server

    if ($WindowsAuth)
    {
        $smoServer.ConnectionContext.LoginSecure = $true
    }
    else
    {
        if ([string]::IsNullOrWhiteSpace($UserId))
        {
            throw "UseWindowsAuthentication = false nhung chua dien SqlUser."
        }
        $smoServer.ConnectionContext.LoginSecure = $false
        $smoServer.ConnectionContext.Login = $UserId
        $smoServer.ConnectionContext.Password = $Password
    }

    $db = $smoServer.Databases[$Database]
    if (-not $db)
    {
        throw ("Khong tim thay database: {0}" -f $Database)
    }

    return @{ Server = $smoServer; Database = $db; DatabaseName = $Database }
}
